xml.Script:
        MirrorColor := 'E0C07D';

        W := 0.5;
        D := W / 3;

        if not VarExists('Rx') then
          RX :=  -9 * Pi / 180
        else
          RX :=  Rx * Pi / 180;
          RX :=  -90 * Pi / 180;

        if not VarExists('Ry') then
          RY := -69 * Pi / 180
        else
          RY :=  Ry * Pi / 180;

        if not VarExists('Rz') then
          RZ :=  65 * Pi / 180
        else
          RZ :=  Rz * Pi / 180;

        if not VarExists('Ra') then
          Ra :=  96 * Pi / 180
        else
          Ra :=  Ra * Pi / 180;

        DR := 0.1;
        if not VarExists('NR') then
          NR := 13;
//        RequestNumbers('Input order', 'Order:', NR);

        RX := RX + (NR mod 3 - 1) * DR;
        RY := RY + (NR div 3 mod 3 - 1) * DR;
        RZ := RZ + (NR div 9 mod 3 - 1) * DR;

RX := -0.27076963267949; RY := -1.045167183876087; RZ := 1.348554013796314;
DR := 0.03;

    A1 := 30 * Pi / 180;
        A2 := 30 * Pi / 180;




        
        AngleX := RX; //45 * Pi / 180;
        AngleY := RY; //45 * Pi / 180;
        AngleZ := RZ; //45 * Pi / 180;


        procedure Rotate(i);
        begin
            temp := ay[i] * cos(AngleX) - az[i] * sin(AngleX);
            az[i] := ay[i] * sin(AngleX) + az[i] * cos(AngleX);
            ay[i] := temp;

            temp := az[i] * cos(AngleY) - ax[i] * sin(AngleY);
            ax[i] := az[i] * sin(AngleY) + ax[i] * cos(AngleY);
            az[i] := temp;

            temp := ax[i] * cos(AngleZ) - ay[i] * sin(AngleZ);
            ay[i] := ax[i] * sin(AngleZ) + ay[i] * cos(AngleZ);
            ax[i] := temp;
        end;

        // initial axes
        ax[0] := 1; ay[0] := 1; az[0] := 1;
        ax[1] :=-1; ay[1] :=-1; az[1] := 1;
        ax[2] :=-1; ay[2] := 1; az[2] :=-1;
        ax[3] := 1; ay[3] :=-1; az[3] :=-1;

        for i := 0 to 3 do
            Rotate(i);

        function Distp(p,px,py,pz);
        begin
            Result := Abs(px * ax[p] + py * ay[p] + pz * az[p]);
        end;

        function Crit();
        begin
            Result := 0;
            Result := Result + Distp(0,     W, W*0.05,  W    );
            Result := Result + Distp(1,     W, W*0.05,  W    );
//            Result := Result + Distp(2,    -W,    -W, -W*0.2);
//            Result := Result + Distp(3,-W*0.8,     W,  W    );
            Result 	:= Result + Distp(0,     W*0.85, -W,  W    );
        end;
//        ShowMessage(Crit);

        MMM := 100;
        for ix := -1 to 1 do
          for iy := -1 to 1 do
            for iz := -1 to 1 do begin
                AngleX := RX + DR * ix;
                AngleY := RY + DR * iy;
                AngleZ := RZ + DR * iz;

                // initial axes
                ax[0] := 1; ay[0] := 1; az[0] := 1;
                ax[1] :=-1; ay[1] :=-1; az[1] := 1;
                ax[2] :=-1; ay[2] := 1; az[2] :=-1;
                ax[3] := 1; ay[3] :=-1; az[3] :=-1;

                for i := 0 to 3 do
                    Rotate(i);

                C := Crit;
                //ShowMessage(RZ);
                if C < MMM then begin
                    MMM := C;
                    mIx := ix;
                    mIy := iy;
                    mIz := iz;
                end;
            end;
        ShowMessage(IntToStr(mix) + ' ' + IntToStr(miy) + ' ' + IntToStr(miz) + ' ' + FloatToStr(MMM));
ShowMessage('RX := ' + FloatToStr(RX + DR * mIx) + '; RY := ' + FloatToStr(RY + DR * mIy) + '; RZ := ' + FloatToStr(RZ + DR * mIz) + ';');

